<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ApiError, getApiData } from '../services/api'
interface EmailRow {notification_id:number;appointment_id:number|null;patient_id:number|null;type:string;subject:string|null;status:string;scheduled_at:string|null;sent_at:string|null;error_message:string|null;patient_name:string;source:'email'|'in_app';message:string|null}
const rows=ref<EmailRow[]>([]);const loading=ref(true);const error=ref('')
onMounted(async()=>{try{rows.value=await getApiData<EmailRow[]>('/api/email-notifications')}catch(e){error.value=e instanceof ApiError?e.message:'Could not load email history.'}finally{loading.value=false}})
</script>
<template><section class="page-heading"><div><p class="eyebrow">CLINIC COMMUNICATIONS</p><h1>Email &amp; Notification Log</h1><p class="muted">One history for appointment emails and in-app notifications sent to patients and clinic users.</p></div></section><section v-if="loading" class="surface empty-state"><span class="loading-dot"/><strong>Loading communication history</strong></section><section v-else-if="error" class="surface empty-state"><strong>Communication history unavailable</strong><p>{{ error }}</p></section><section v-else-if="!rows.length" class="surface empty-state"><strong>No communications have been logged</strong><p>Appointment email and in-app notification activity will appear here.</p></section><section v-else class="surface table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Recipient</th><th>Channel</th><th>Appointment</th><th>Type / subject</th><th>Message</th><th>Status / error</th></tr></thead><tbody><tr v-for="row in rows" :key="`${row.source}-${row.notification_id}`"><td>{{ row.sent_at||row.scheduled_at||'—' }}</td><td>{{ row.patient_name }}</td><td>{{ row.source==='email'?'Email':'In-app' }}</td><td>{{ row.appointment_id ? `#${row.appointment_id}` : '—' }}</td><td>{{ row.subject||row.type }}</td><td>{{ row.message||'—' }}</td><td><span class="status-badge" :data-status="row.status">{{ row.status }}</span><small v-if="row.error_message" class="table-secondary">{{ row.error_message }}</small></td></tr></tbody></table></section></template>
